-- IA 1.1 → 1.2: Owner decisions D2, D4, D5, D6, D8, D12, D13, D16, D19 (docs/questionbank/decisions.md)
-- Generated by `npm run qb:patch`. Run once in the Supabase SQL Editor. One transaction: if any step
-- or the validation fails, nothing is saved. Publishes the new version (testing databases).
DO $qbpatch$
DECLARE
  v uuid;
  n integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.qb_versions WHERE test_code = 'IA' AND version_label = '1.1' AND status = 'live') THEN
    RAISE EXCEPTION 'IA 1.1 must be the live version.';
  END IF;
  v := public.qb_start_new_version('IA', '1.2');
  UPDATE public.qb_versions SET change_note = 'Owner decisions D2, D4, D5, D6, D8, D12, D13, D16, D19 (docs/questionbank/decisions.md)' WHERE id = v;

  -- 1. D2: set_option
  UPDATE public.qb_options SET exclusive = true WHERE version_id = v AND qid = 'R1' AND option_code = 'none_of_these';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 1 (set_option, D2): expected 1 option, got %', n; END IF;

  -- 2. D16: set_question
  UPDATE public.qb_questions SET scored = 'no' WHERE version_id = v AND qid = 'R2';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 2 (set_question, D16): expected 1 question, got %', n; END IF;

  -- 3. D16: set_question
  UPDATE public.qb_questions SET scored = 'no' WHERE version_id = v AND qid = 'R3';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 3 (set_question, D16): expected 1 question, got %', n; END IF;

  -- 4. D16: set_question
  UPDATE public.qb_questions SET scored = 'no' WHERE version_id = v AND qid = 'R4';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 4 (set_question, D16): expected 1 question, got %', n; END IF;

  -- 5. D16: set_question
  UPDATE public.qb_questions SET scored = 'no' WHERE version_id = v AND qid = 'R5';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 5 (set_question, D16): expected 1 question, got %', n; END IF;

  -- 6. D16: set_question
  UPDATE public.qb_questions SET scored = 'no' WHERE version_id = v AND qid = 'R6';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 6 (set_question, D16): expected 1 question, got %', n; END IF;

  -- 7. D8: add_text
  INSERT INTO public.qb_texts (version_id, key, module_code, band, text_en, text_hi)
  SELECT v, 'MED_ONSET', NULL, NULL, t.text_en, t.text_hi
  FROM public.qb_texts t JOIN public.qb_versions x ON x.id = t.version_id
  WHERE x.test_code = 'MA' AND x.status = 'live' AND t.key = 'MED_ONSET';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 7 (add_text, D8): expected 1 text, got %', n; END IF;

  -- 8. D8: add_flag
  UPDATE public.qb_flags SET sort = sort + 1 WHERE version_id = v
    AND sort > (SELECT sort FROM public.qb_flags WHERE version_id = v AND key = 'MED_FEMALE');
  INSERT INTO public.qb_flags (version_id, key, condition, effects, is_protected, sort)
  SELECT v, 'MED_ONSET', $qbj${"all":[{"fact":"answer","q":"R2","op":"eq","value":"yes"},{"not":{"fact":"flag","key":"MED_MALE"}},{"not":{"fact":"flag","key":"MED_FEMALE"}}]}$qbj$::jsonb, $qbj${"report_block":"MED_ONSET","dashboard_tag":"MED_ONSET"}$qbj$::jsonb, false, sort + 1 FROM public.qb_flags WHERE version_id = v AND key = 'MED_FEMALE';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 8 (add_flag, D8): expected 1 flag, got %', n; END IF;

  -- 9. D4: add_flag
  INSERT INTO public.qb_flags (version_id, key, condition, effects, is_protected, sort)
  SELECT v, 'SEPARATION_THOUGHTS', $qbj${"fact":"answer","q":"C11","op":"eq","value":"often"}$qbj$::jsonb, $qbj${"dashboard_tag":"SEPARATION_THOUGHTS","printed":false}$qbj$::jsonb, false, coalesce(max(sort), 0) + 1 FROM public.qb_flags WHERE version_id = v;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 9 (add_flag, D4): expected 1 flag, got %', n; END IF;

  -- 10. D5: add_flag
  INSERT INTO public.qb_flags (version_id, key, condition, effects, is_protected, sort)
  SELECT v, 'RELATIONSHIP_SAFETY_CHECK', $qbj${"fact":"answer","q":"T7","op":"in","value":["never","rarely"]}$qbj$::jsonb, $qbj${"dashboard_tag":"RELATIONSHIP_SAFETY_CHECK","force_format":"individual","printed":false}$qbj$::jsonb, false, coalesce(max(sort), 0) + 1 FROM public.qb_flags WHERE version_id = v;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 10 (add_flag, D5): expected 1 flag, got %', n; END IF;

  -- 11. D6: add_flag
  INSERT INTO public.qb_flags (version_id, key, condition, effects, is_protected, sort)
  SELECT v, 'LOW_REPAIR_MOTIVATION', $qbj${"fact":"answer","q":"T8","op":"in","value":["never","rarely"]}$qbj$::jsonb, $qbj${"dashboard_tag":"LOW_REPAIR_MOTIVATION","force_format":"individual","printed":false}$qbj$::jsonb, false, coalesce(max(sort), 0) + 1 FROM public.qb_flags WHERE version_id = v;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 11 (add_flag, D6): expected 1 flag, got %', n; END IF;

  -- 12. D19: set_flag
  UPDATE public.qb_flags SET effects = effects || $qbj${"notify":["coordinator","counsellor"]}$qbj$::jsonb WHERE version_id = v AND key = 'CRISIS';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 12 (set_flag, D19): expected 1 flag, got %', n; END IF;

  -- 13. D19: set_flag
  UPDATE public.qb_flags SET effects = effects || $qbj${"notify":["coordinator","counsellor"]}$qbj$::jsonb WHERE version_id = v AND key = 'SAFETY';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 13 (set_flag, D19): expected 1 flag, got %', n; END IF;

  -- 14. D12: set_scoring
  UPDATE public.qb_scoring SET gate = gate || $qbj${"min_choices":1}$qbj$::jsonb WHERE version_id = v;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 14 (set_scoring, D12): expected 1 qb_scoring row, got %', n; END IF;

  -- 15. D12: set_format_rules
  DELETE FROM public.qb_format_rules WHERE version_id = v;
  INSERT INTO public.qb_format_rules (version_id, key, condition, format, split, add_text_key, sort) VALUES (v, 'SAFETY_INDIVIDUAL', $qbj${"fact":"flag","key":"SAFETY"}$qbj$::jsonb, 'individual', NULL, NULL, 1);
  INSERT INTO public.qb_format_rules (version_id, key, condition, format, split, add_text_key, sort) VALUES (v, 'SOLO_INDIVIDUAL', $qbj${"fact":"path","op":"eq","value":"solo"}$qbj$::jsonb, 'individual', NULL, NULL, 2);
  INSERT INTO public.qb_format_rules (version_id, key, condition, format, split, add_text_key, sort) VALUES (v, 'PARTNER_NOT_WILLING', $qbj${"not":{"fact":"answer","q":"I6","op":"eq","value":"yes_and_they_are_willing_to_join_sessions"}}$qbj$::jsonb, 'individual', NULL, NULL, 3);
  INSERT INTO public.qb_format_rules (version_id, key, condition, format, split, add_text_key, sort) VALUES (v, 'COUPLE_ONLY', $qbj${"fact":"chosen_kinds","op":"only","value":["couple"]}$qbj$::jsonb, 'couple', NULL, NULL, 4);
  INSERT INTO public.qb_format_rules (version_id, key, condition, format, split, add_text_key, sort) VALUES (v, 'INDIVIDUAL_ONLY', $qbj${"fact":"chosen_kinds","op":"only","value":["individual"]}$qbj$::jsonb, 'individual_partner_joins', NULL, NULL, 5);
  INSERT INTO public.qb_format_rules (version_id, key, condition, format, split, add_text_key, sort) VALUES (v, 'MIXED', $qbj${"fact":"chosen_kinds","op":"includes","value":["couple","individual"]}$qbj$::jsonb, 'mixed', $qbj${"4":[3,1],"6":[4,2],"8":[5,3],"12":[7,5]}$qbj$::jsonb, NULL, 6);
  INSERT INTO public.qb_format_rules (version_id, key, condition, format, split, add_text_key, sort) VALUES (v, 'DEFAULT_INDIVIDUAL', $qbj${"all":[]}$qbj$::jsonb, 'individual', NULL, NULL, 7);

  -- 16. D13: set_report_rules
  UPDATE public.qb_report_rules SET interpretation = interpretation || $qbj${"fallback":"core"}$qbj$::jsonb WHERE version_id = v;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 16 (set_report_rules, D13): expected 1 qb_report_rules row, got %', n; END IF;

  -- 17. D5: set_test_case
  UPDATE public.qb_test_cases SET answers = answers || $qbj${"T7":"sometimes"}$qbj$::jsonb, notes = 'Female 34, married 9 yrs, chose G + A; partner willing. Intended module %: CORE 28/33 = 85% (High) · G 15/18 = 83% (High) · A 16/24 = 67% (Moderate). Points SEVERITY 3 + DURATION 3 + IMPACT 3 + MULTI_AREA 2 + PRIOR_ATTEMPTS 1 + TRUST_WOUND 1 = 13. IA 1.2: T7 changed from Rarely to Sometimes so RELATIONSHIP_SAFETY_CHECK (D5) does not fire; expected tier 12 and format Couple are unchanged from the workbook.' WHERE version_id = v AND name = 'Worked example D';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Patch operation 17 (set_test_case, D5): expected 1 test case, got %', n; END IF;

  -- 18. D5: add_test_case
  INSERT INTO public.qb_test_cases (version_id, name, source, context, answers, expected, verified, notes) VALUES (v, 'T7_RARELY', 'manual', $qbj${"sex":"female","age":30,"path":"partner"}$qbj$::jsonb, $qbj${"I1":"25_34","I2":"female","I3":"married","I4":"3_10_years","I5":"india","I6":"yes_and_they_are_willing_to_join_sessions","I7":"no_children","I8":"english","G1":["G","A"],"C1":"rarely","C2":"rarely","C3":"sometimes","C4":"rarely","C5":"rarely","C6":"sometimes","C7":"sometimes","C8":"rarely","C9":"sometimes","C10":"rarely","C11":"rarely","C12":"sometimes","T7":"rarely","T2":"sometimes","T3":"sometimes","T4":"sometimes","T5":"sometimes","T6":"sometimes","T1":"yes","T8":"often","A1":"sometimes","A2":"sometimes","A3":"rarely","A4":"rarely","A5":"rarely","A6":"rarely","A7":"sometimes","A8":"sometimes","D1":"3_12_months","D2":"a_little","D3":"nothing_yet","D4":"yes","R1":["none_of_these"],"R2":"no","R5":"no","R6":"no","R3":"no"}$qbj$::jsonb, $qbj${"bands":{"CORE":"Mild","G":"Moderate","A":"Mild"},"primary":"G","points":{"SEVERITY":2,"DURATION":1,"IMPACT":1,"MULTI_AREA":0,"PRIOR_ATTEMPTS":0,"TRUST_WOUND":1,"TOTAL":5},"tier":6,"format":"individual","flags":["RELATIONSHIP_SAFETY_CHECK"],"layout":"standard"}$qbj$::jsonb, false, 'Female 30, partner willing, chose G + A, T7 = Rarely (D5). Intended module %: CORE 13/33 = 39% (Mild) · G 12/18 = 67% (Moderate) · A 10/24 = 42% (Mild). Points SEVERITY 2 + DURATION 1 + IMPACT 1 + MULTI_AREA 0 + PRIOR_ATTEMPTS 0 + TRUST_WOUND 1 = 5. Couple modules with a willing partner would be Couple; RELATIONSHIP_SAFETY_CHECK forces individual. No SAFETY flag or block.');

  -- 19. D6: add_test_case
  INSERT INTO public.qb_test_cases (version_id, name, source, context, answers, expected, verified, notes) VALUES (v, 'T8_NEVER', 'manual', $qbj${"sex":"female","age":33,"path":"partner"}$qbj$::jsonb, $qbj${"I1":"25_34","I2":"female","I3":"married","I4":"3_10_years","I5":"india","I6":"yes_and_they_are_willing_to_join_sessions","I7":"no_children","I8":"english","G1":["G"],"C1":"rarely","C2":"rarely","C3":"sometimes","C4":"rarely","C5":"rarely","C6":"sometimes","C7":"sometimes","C8":"rarely","C9":"sometimes","C10":"rarely","C11":"rarely","C12":"sometimes","T7":"often","T2":"often","T3":"often","T4":"sometimes","T5":"sometimes","T6":"sometimes","T1":"yes","T8":"never","D1":"1_3_years","D2":"quite_a_lot","D3":"nothing_yet","D4":"yes","R1":["none_of_these"],"R2":"no","R5":"no","R6":"no","R3":"no"}$qbj$::jsonb, $qbj${"bands":{"CORE":"Mild","G":"Moderate"},"primary":"G","points":{"SEVERITY":2,"DURATION":2,"IMPACT":2,"MULTI_AREA":0,"PRIOR_ATTEMPTS":0,"TRUST_WOUND":1,"TOTAL":7},"tier":8,"format":"individual","flags":["LOW_REPAIR_MOTIVATION"],"layout":"standard"}$qbj$::jsonb, false, 'Female 33, partner willing, chose G only, T8 = Never (D6). Intended module %: CORE 13/33 = 39% (Mild) · G 12/18 = 67% (Moderate). Points SEVERITY 2 + DURATION 2 + IMPACT 2 + MULTI_AREA 0 + PRIOR_ATTEMPTS 0 + TRUST_WOUND 1 = 7. G only with a willing partner would be Couple; LOW_REPAIR_MOTIVATION forces individual. T7 = Often so RELATIONSHIP_SAFETY_CHECK does not fire.');

  -- 20. D8: add_test_case
  INSERT INTO public.qb_test_cases (version_id, name, source, context, answers, expected, verified, notes) VALUES (v, 'R2_PNS_ONSET', 'manual', $qbj${"sex":"prefer_not_to_say","age":28,"path":"partner"}$qbj$::jsonb, $qbj${"I1":"25_34","I2":"prefer_not_to_say","I3":"married","I4":"3_10_years","I5":"india","I6":"yes_and_they_are_willing_to_join_sessions","I7":"no_children","I8":"english","G1":["A"],"C1":"rarely","C2":"rarely","C3":"sometimes","C4":"rarely","C5":"rarely","C6":"sometimes","C7":"sometimes","C8":"rarely","C9":"sometimes","C10":"rarely","C11":"rarely","C12":"sometimes","A1":"sometimes","A2":"sometimes","A3":"sometimes","A4":"sometimes","A5":"sometimes","A6":"sometimes","A7":"rarely","A8":"rarely","D1":"3_12_months","D2":"a_little","D3":"nothing_yet","D4":"yes","R1":["none_of_these"],"R2":"yes","R5":"no","R6":"no"}$qbj$::jsonb, $qbj${"bands":{"CORE":"Mild","A":"Moderate"},"primary":"A","points":{"SEVERITY":2,"DURATION":1,"IMPACT":1,"MULTI_AREA":0,"PRIOR_ATTEMPTS":0,"TRUST_WOUND":0,"TOTAL":4},"tier":4,"format":"couple","flags":["MED_ONSET"],"layout":"standard"}$qbj$::jsonb, false, 'Prefer not to say 28, partner willing, chose A only, R2 = Yes (D8). Intended module %: CORE 13/33 = 39% (Mild) · A 16/24 = 67% (Moderate). Points SEVERITY 2 + DURATION 1 + IMPACT 1 + MULTI_AREA 0 + PRIOR_ATTEMPTS 0 + TRUST_WOUND 0 = 4. R3 and R4 are not shown (not Female/Male, neither C nor D chosen), so MED_MALE and MED_FEMALE cannot fire; MED_ONSET prints its block.');

  -- 21. D4: add_test_case
  INSERT INTO public.qb_test_cases (version_id, name, source, context, answers, expected, verified, notes) VALUES (v, 'C11_OFTEN', 'manual', $qbj${"sex":"female","age":35,"path":"partner"}$qbj$::jsonb, $qbj${"I1":"35_44","I2":"female","I3":"married","I4":"3_10_years","I5":"india","I6":"yes_and_they_are_willing_to_join_sessions","I7":"no_children","I8":"english","G1":["B"],"C11":"often","C1":"sometimes","C2":"sometimes","C3":"sometimes","C4":"rarely","C5":"rarely","C6":"sometimes","C7":"sometimes","C8":"rarely","C9":"sometimes","C10":"rarely","C12":"sometimes","B4":"no","B1":"sometimes","B2":"sometimes","B3":"sometimes","B5":"sometimes","B6":"rarely","B7":"rarely","B8":"rarely","D1":"3_12_months","D2":"a_little","D3":"nothing_yet","D4":"yes","R1":["none_of_these"],"R2":"no","R5":"no","R6":"no","R3":"no"}$qbj$::jsonb, $qbj${"bands":{"CORE":"Mild","B":"Mild"},"primary":"B","points":{"SEVERITY":1,"DURATION":1,"IMPACT":1,"MULTI_AREA":0,"PRIOR_ATTEMPTS":0,"TRUST_WOUND":0,"TOTAL":3},"tier":4,"format":"couple","flags":["SEPARATION_THOUGHTS"],"layout":"standard"}$qbj$::jsonb, false, 'Female 35, partner willing, chose B only, C11 = Often (D4). Intended module %: CORE 13/33 = 39% (Mild) · B 10/24 = 42% (Mild). Points SEVERITY 1 + DURATION 1 + IMPACT 1 + MULTI_AREA 0 + PRIOR_ATTEMPTS 0 + TRUST_WOUND 0 = 3. Same answers with C11 = Sometimes: CORE 12/33 = 36% (Mild), same points (3) and tier (4); only the SEPARATION_THOUGHTS tag differs. The tag adds no points and is not printed.');

  -- 22. D13: add_test_case
  INSERT INTO public.qb_test_cases (version_id, name, source, context, answers, expected, verified, notes) VALUES (v, 'LOW_MODULE_FALLBACK', 'manual', $qbj${"sex":"female","age":26,"path":"partner"}$qbj$::jsonb, $qbj${"I1":"25_34","I2":"female","I3":"married","I4":"3_10_years","I5":"india","I6":"yes_and_they_are_willing_to_join_sessions","I7":"no_children","I8":"english","G1":["B"],"C1":"rarely","C2":"rarely","C3":"sometimes","C4":"rarely","C5":"rarely","C6":"sometimes","C7":"sometimes","C8":"rarely","C9":"sometimes","C10":"rarely","C11":"rarely","C12":"sometimes","B4":"no","B1":"rarely","B2":"rarely","B3":"rarely","B5":"sometimes","B6":"never","B7":"never","B8":"never","D1":"less_than_3_months","D2":"a_little","D3":"nothing_yet","D4":"yes","R1":["none_of_these"],"R2":"no","R5":"no","R6":"no","R3":"no"}$qbj$::jsonb, $qbj${"bands":{"CORE":"Mild","B":"Low"},"primary":"B","points":{"SEVERITY":0,"DURATION":0,"IMPACT":1,"MULTI_AREA":0,"PRIOR_ATTEMPTS":0,"TRUST_WOUND":0,"TOTAL":1},"tier":4,"format":"couple","flags":[],"layout":"standard","interpretation_keys":["INTERP_CORE_MILD"]}$qbj$::jsonb, false, 'Female 26, partner willing, chose B, B band Low, core Mild (D13). Intended module %: CORE 13/33 = 39% (Mild) · B 4/24 = 17% (Low). Points SEVERITY 0 + DURATION 0 + IMPACT 1 + MULTI_AREA 0 + PRIOR_ATTEMPTS 0 + TRUST_WOUND 0 = 1. There is no INTERP_B_LOW, so the primary line falls back to the core text for the core band (INTERP_CORE_MILD); it is printed once, not repeated for the core line.');

  -- 23. D19: add_test_case
  INSERT INTO public.qb_test_cases (version_id, name, source, context, answers, expected, verified, notes) VALUES (v, 'SAFETY_BEATS_COUPLE', 'manual', $qbj${"sex":"female","age":40,"path":"partner"}$qbj$::jsonb, $qbj${"I1":"35_44","I2":"female","I3":"married","I4":"3_10_years","I5":"india","I6":"yes_and_they_are_willing_to_join_sessions","I7":"no_children","I8":"english","G1":["A","B"],"C1":"rarely","C2":"rarely","C3":"sometimes","C4":"rarely","C5":"rarely","C6":"sometimes","C7":"sometimes","C8":"rarely","C9":"sometimes","C10":"rarely","C11":"rarely","C12":"sometimes","A1":"sometimes","A2":"sometimes","A3":"sometimes","A4":"sometimes","A5":"sometimes","A6":"sometimes","A7":"rarely","A8":"rarely","B4":"no","B1":"sometimes","B2":"sometimes","B3":"sometimes","B5":"sometimes","B6":"rarely","B7":"rarely","B8":"rarely","D1":"3_12_months","D2":"quite_a_lot","D3":"nothing_yet","D4":"yes","R1":["none_of_these"],"R2":"no","R5":"no","R6":"yes","R3":"no"}$qbj$::jsonb, $qbj${"bands":{"CORE":"Mild","A":"Moderate","B":"Mild"},"primary":"A","points":{"SEVERITY":2,"DURATION":1,"IMPACT":2,"MULTI_AREA":0,"PRIOR_ATTEMPTS":0,"TRUST_WOUND":0,"TOTAL":5},"tier":6,"format":"individual","flags":["SAFETY"],"layout":"standard","notify":["coordinator","counsellor"]}$qbj$::jsonb, false, 'Female 40, partner willing, chose A + B (couple only), R6 = Yes. Intended module %: CORE 13/33 = 39% (Mild) · A 16/24 = 67% (Moderate) · B 10/24 = 42% (Mild). Points SEVERITY 2 + DURATION 1 + IMPACT 2 + MULTI_AREA 0 + PRIOR_ATTEMPTS 0 + TRUST_WOUND 0 = 5. Couple modules only with a willing partner would be Couple; SAFETY forces individual and prints the SAFETY block.');

  -- Zero validation errors, or nothing is saved.
  PERFORM public.qb_raise_if_invalid(v);
  PERFORM public.qb_submit_for_review(v);
  PERFORM public.qb_publish(v, 'IA 1.2: owner decisions D2, D4, D5, D6, D8, D12, D13, D16, D19 (testing)');
  RAISE NOTICE 'IA 1.2 is live (%).', v;
END
$qbpatch$;
